package com.bank.cache;

import java.util.HashMap;
import java.util.Map;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class LruCacheDemo {

    private static final Logger log = Logger.getLogger(LruCacheDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) {
            root.removeHandler(h);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Cache of account balances, capacity 2 for easy demonstration.
        LruCache cache = new LruCache(2);

        cache.put("SAV2001", 1000000L);          // Rajesh
        cache.put("CUR3001", 250000L);           // Priya
        log.info(() -> "get SAV2001 -> " + cache.get("SAV2001"));   // hit, promotes Rajesh

        cache.put("SAV4002", 75000L);            // new entry: evicts least recent (CUR3001)
        log.info(() -> "get CUR3001 -> " + cache.get("CUR3001"));   // miss, was evicted
        log.info(() -> "get SAV2001 -> " + cache.get("SAV2001"));   // hit, still present
        log.info(() -> "get SAV4002 -> " + cache.get("SAV4002"));   // hit
    }
}

