class LruCache {

    private static final Logger log = Logger.getLogger(LruCache.class.getName());

    private final int capacity;
    private final Map<String, Node> map = new HashMap<>();
    private final Node head;   // sentinel: most-recently-used side
    private final Node tail;   // sentinel: least-recently-used side

    LruCache(int capacity) {
        this.capacity = capacity;
        this.head = new Node(null, 0);
        this.tail = new Node(null, 0);
        head.next = tail;
        tail.prev = head;
    }

    // O(1): look up, and if found promote to most recently used.
    Long get(String key) {
        Node node = map.get(key);
        if (node == null) {
            log.fine(() -> "MISS " + key);
            return null;
        }
        moveToFront(node);
        log.fine(() -> "HIT " + key + " -> " + node.value);
        return node.value;
    }

    // O(1): insert or update, evict least-recently-used if over capacity.
    void put(String key, long value) {
        Node existing = map.get(key);
        if (existing != null) {
            existing.value = value;
            moveToFront(existing);
            return;
        }
        Node node = new Node(key, value);
        map.put(key, node);
        addFront(node);
        if (map.size() > capacity) {
            Node lru = tail.prev;           // least recently used sits before tail
            remove(lru);
            map.remove(lru.key);            // CRITICAL: also drop from the map
            log.info(() -> "EVICT " + lru.key);
        }
    }

    private void addFront(Node node) {
        node.next = head.next;
        node.prev = head;
        head.next.prev = node;
        head.next = node;
    }

    private void remove(Node node) {
        node.prev.next = node.next;
        node.next.prev = node.prev;
    }

    private void moveToFront(Node node) {
        remove(node);
        addFront(node);
    }
}

